106:   function rollReward(box,forceLegendary) {
107:     const brawlerChance=box.brawlerChance;
108:     const r=Math.random();
109:     if (forceLegendary || r < brawlerChance) {
110:       let pool=brawlers.filter(b=>!state.owned[b.id]);
111:       if (forceLegendary) {
112:         const legendary=pool.filter(b=>b.rarity==='Legendary');
113:         if (legendary.length) return makeBrawlerReward(legendary[0]);
114:       }
115:       if (pool.length) {
116:         const weighted=pool.map(b=>({b,weight:rarityInfo(b.rarity).weight}));
117:         return makeBrawlerReward(weightedPick(weighted).b);
118:       }
119:       return {type:'coins',amount:randomInt(35,65),label:'Coin bonus',icon:'◆',note:'MAXED OUT',rarity:'Bonus'};
120:     }
121:     if (r < brawlerChance + .28) return {type:'power',amount:randomInt(...box.points),label:'Power points',icon:'⚡',note:'POWER UP',rarity:'Power'};
122:     return {type:'coins',amount:randomInt(...box.coins),label:'Coins',icon:'◆',note:'CURRENCY',rarity:'Coins'};
123:   }
124:   function makeBrawlerReward(brawler) {
125:     const info=rarityInfo(brawler.rarity);
126:     return {type:'brawler',id:brawler.id,brawler,amount:1,label:brawler.name,icon:brawler.icon,note:brawler.rarity.toUpperCase(),rarity:brawler.rarity,color:info.color,bg:info.bg};
127:   }
128:   function openBox() {
129:     if (isOpening || !$('reveal-overlay').classList.contains('hidden')) return;
130:     isOpening=true;
131:     const box=chosenBox();
132:     $('open-button').disabled=true;
133:     $('crate-stage').classList.add('opening');
134:     window.setTimeout(()=>{
135:       $('crate-stage').classList.remove('opening');
136:       const forceLegendary=state.luck>=29 && brawlers.some(b=>b.rarity==='Legendary'&&!state.owned[b.id]);
137:       let rewards=[];
138:       for(let i=0;i<box.rewards;i++) rewards.push(rollReward(box,forceLegendary&&i===0));
139:       applyRewards(rewards,box,forceLegendary);
140:       state.opened++;
141:       state.quests.open3=(state.quests.open3||0)+1;
142:       if(box.id==='starr') state.quests.starr1=(state.quests.starr1||0)+1;
143:       state.luck=forceLegendary?0:Math.min(30,state.luck+1);
144:       if(rewards.some(item=>item.rarity==='Legendary')) state.luck=0;
145:       const highest=rewards.find(item=>item.type==='brawler' && item.rarity==='Legendary')||rewards.find(item=>item.type==='brawler');
146:       if(highest) state.best=highest.label;
147:       state.recent=rewards.slice().reverse().map(item=>({label:item.label,note:item.note,icon:item.icon,color:item.color||rarityInfo(item.rarity).color,bg:item.bg||rarityInfo(item.rarity).bg})).concat(state.recent).slice(0,4);
148:       save();render();showReveal(rewards,box);
149:       $('open-button').disabled=false;isOpening=false;
150:     },750);
151:   }
152:   function applyRewards(rewards,box,forceLegendary) {
153:     rewards.forEach(item=>{
154:       if(item.type==='coins'){state.coins+=item.amount;return;}
155:       if(item.type==='power'){
156:         const unlocked=brawlers.filter(b=>state.owned[b.id]);
157:         if(unlocked.length){const target=unlocked[Math.floor(Math.random()*unlocked.length)];state.power[target.id]=(state.power[target.id]||0)+item.amount;item.label=`${target.name} +${item.amount}`;item.note=`POWER POINTS · LV ${levelOf(target.id)}`;item.icon='⚡';item.color='#b893ff';item.bg='#453766';}
158:         else {state.coins+=item.amount;item.type='coins';item.label='Coins';item.note='CURRENCY';item.icon='◆';item.color='#ffd15a';item.bg='#51452d';}
159:         return;
160:       }
161:       const b=item.brawler;
162:       if(!state.owned[b.id]){state.owned[b.id]=true;state.power[b.id]=0;state.quests.collect2=(state.quests.collect2||0)+1;item.isNew=true;}
163:       else {state.coins+=45;item.type='duplicate';item.label=`${b.name} duplicate`;item.note='+45 COINS';item.icon='◆';item.amount=45;item.color='#ffd15a';item.bg='#51452d';}
164:     });
165:     if(forceLegendary) showToast('LEGENDARY PITY! Guaranteed drop unlocked.');
166:   }
167:   function showReveal(rewards,box) {
168:     $('reveal-kicker').textContent=`${box.name} OPENED!`;
169:     $('reveal-title').textContent=rewards.some(r=>r.isNew)?'NEW BRAWLER!':'NICE HAUL!';
