171:       const info=item.color?{color:item.color,bg:item.bg}:rarityInfo(item.rarity);
172:       const label=item.label;
173:       return `<div class="reveal-item ${item.isNew?'new':''}" style="--rarity:${info.color};--rarity-bg:${info.bg}"><div class="reward-icon">${item.icon}</div><b>${label}</b><small>${item.isNew?'NEW BRAWLER':item.note}</small></div>`;
174:     }).join('');
175:     $('reveal-overlay').classList.remove('hidden');
176:   }
177:   function closeReveal(){ $('reveal-overlay').classList.add('hidden'); }
178:   function claimQuest(id) {
179:     const quest=questDefs.find(q=>q.id===id);
180:     if(!quest || state.claimed[id] || (state.quests[id]||0)<quest.goal) return;
181:     state.claimed[id]=true;state.coins+=quest.reward;save();render();showToast(`Quest complete! +${quest.reward} coins`);
182:   }
183:   function setView(view) {
184:     document.querySelectorAll('.view').forEach(el=>el.classList.add('hidden'));
185:     const target=$(`${view}-view`);if(target)target.classList.remove('hidden');
