190:     const box=chosenBox(), b=box.brawlerChance*100, power=28, coins=100-b-power;
191:     const rows=[['Coins',coins,'#ffd15a'],['Power points',power,'#b893ff'],['Brawler unlock',b,'#72d49b']];
192:     $('odds-list').innerHTML=rows.map(([name,pct,color])=>`<div class="odds-row" style="--rarity:${color}"><span>${name}</span><div class="odds-track"><i style="width:${pct}%"></i></div><small>${pct.toFixed(0)}%</small></div>`).join('');
193:     $('modal-title').textContent=`${box.short} drop rates`;
194:     $('modal-backdrop').classList.remove('hidden');
195:   }
