198:   $('open-again').addEventListener('click',openBox);
199:   $('box-tabs').addEventListener('click',e=>{const tab=e.target.closest('[data-box]');if(!tab)return;state.box=tab.dataset.box;save();renderBoxes();});
200:   $('odds-button').addEventListener('click',showOdds);
201:   $('modal-close').addEventListener('click',()=>$('modal-backdrop').classList.add('hidden'));
202:   $('modal-done').addEventListener('click',()=>$('modal-backdrop').classList.add('hidden'));
203:   $('modal-backdrop').addEventListener('click',e=>{if(e.target===$('modal-backdrop'))$('modal-backdrop').classList.add('hidden');});
204:   $('reveal-close').addEventListener('click',closeReveal);
205:   $('reveal-overlay').addEventListener('click',e=>{if(e.target===$('reveal-overlay'))closeReveal();});
206:   document.addEventListener('click',e=>{
207:     const nav=e.target.closest('[data-view]');if(nav){e.preventDefault();setView(nav.dataset.view);}
208:     const claim=e.target.closest('[data-claim]');if(claim)claimQuest(claim.dataset.claim);
209:     const toast=e.target.closest('[data-toast]');if(toast)showToast(toast.dataset.toast);
210:   });
211:   $('quest-action').addEventListener('click',()=>{
212:     const q=questDefs[0];if(state.claimed[q.id])return;
213:     if((state.quests[q.id]||0)>=q.goal)claimQuest(q.id);else openBox();
214:   });
215:   document.addEventListener('keydown',e=>{
216:     if(e.code==='Escape'){$('modal-backdrop').classList.add('hidden');closeReveal();}
217:     if(e.code==='Space' && !e.repeat && $('modal-backdrop').classList.contains('hidden') && $('reveal-overlay').classList.contains('hidden') && !e.target.matches('button,a,input')){e.preventDefault();openBox();}
218:     if(e.code==='Enter' && !$('reveal-overlay').classList.contains('hidden'))closeReveal();
219:   });
220:   render();
